// Use a parameterized query instead of string concatenation
export async function findCoupon(db, code) {
  const { rows } = await db.query(
    'SELECT id, kind, amount, expires_at, max_uses FROM coupons WHERE code = $1',
    [code.trim().toUpperCase()],
  );
  return rows[0] ?? null;
}

if (coupon.expiresAt && coupon.expiresAt <= now) {
  throw new CouponError('This coupon has expired');
}

switch (coupon.kind) {
  case 'percent':
    return Math.max(0, total - Math.round(total * coupon.amount / 100));
  case 'fixed':
    return Math.max(0, total - coupon.amount);
  default:
    throw new CouponError(`Unknown coupon kind: ${coupon.kind}`);
}
